const num = s => {
  s = String(s).trim().replace(/\s+/g, '').replace(',', '.').replace(/[^\d.\/\-]/g, '');
  if (s === '') return null;
  if (s.includes('/')) { const [a, b] = s.split('/').map(Number); return b ? a / b : null; }
  const v = Number(s); return Number.isFinite(v) ? v : null;
};
const eq = (a, b) => a != null && Math.abs(a - b) < 1e-6;
const norm = s => String(s).toLowerCase().replace(/ё/g, 'е').replace(/[«»"'.,!?\s\-–—]/g, '');
const rnd = (a, b) => a + Math.floor(Math.random() * (b - a + 1));
const pick = a => a[rnd(0, a.length - 1)];
const fmt = v => String(Math.round(v * 100) / 100).replace('.', ',');

/* ================= рисунки ================= */
function barChart(vals, labels, o = {}) {
  const W = 360, H = 250, L = 46, B = 46, T = 14, R = 12, max = o.max || Math.max(...vals) + 1;
  const pw = W - L - R, ph = H - T - B, y = v => T + ph - v / max * ph, bw = pw / vals.length;
  let s = `<svg viewBox="0 0 ${W} ${H}" width="${W}" role="img" aria-label="Столбчатая диаграмма">`;
  for (let i = 0; i <= max; i++) s += `<line x1="${L}" x2="${W - R}" y1="${y(i)}" y2="${y(i)}" stroke="#bbb"/><text x="${L - 8}" y="${y(i) + 4}" text-anchor="end" font-size="12">${i}</text>`;
  vals.forEach((v, i) => { s += `<rect x="${L + i * bw + bw * .2}" y="${y(v)}" width="${bw * .6}" height="${y(0) - y(v)}" fill="#2a5aa8"/><text x="${L + i * bw + bw / 2}" y="${H - B + 18}" text-anchor="middle" font-size="13">${labels[i]}</text>`; });
  s += `<line x1="${L}" x2="${W - R}" y1="${y(0)}" y2="${y(0)}" stroke="#000" stroke-width="2"/>`;
  s += `<text x="${L + pw / 2}" y="${H - 6}" text-anchor="middle" font-size="13" font-weight="700">${o.x || ''}</text>`;
  s += `<text transform="translate(13 ${T + ph / 2}) rotate(-90)" text-anchor="middle" font-size="13" font-weight="700">${o.y || ''}</text></svg>`;
  return s;
}
function tempChart() {
  const v = [-6.5, -14, -5, 6, 10, 14, 16, 15.4, 13.5, 5, -3.4, -10], m = ['янв', 'фев', 'мар', 'апр', 'май', 'июн', 'июл', 'авг', 'сен', 'окт', 'ноя', 'дек'];
  const W = 520, H = 270, L = 44, T = 12, pw = W - L - 10, ph = H - T - 14, y = t => T + (18 - t) / 34 * ph, bw = pw / 12;
  let s = `<svg viewBox="0 0 ${W} ${H}" width="${W}" role="img" aria-label="Диаграмма температуры по месяцам">`;
  for (let t = -16; t <= 18; t += 2) s += `<line x1="${L}" x2="${W - 10}" y1="${y(t)}" y2="${y(t)}" stroke="${t % 4 ? '#ddd' : '#bbb'}"/>` + (t % 4 === 0 || t === 18 ? `<text x="${L - 6}" y="${y(t) + 4}" text-anchor="end" font-size="12">${t < 0 ? '−' + -t : t}</text>` : '');
  v.forEach((t, i) => {
    const y0 = y(0), y1 = y(t);
    s += `<rect x="${L + i * bw + bw * .18}" y="${Math.min(y0, y1)}" width="${bw * .64}" height="${Math.abs(y1 - y0)}" fill="#bdefff" stroke="#2a7fb8" stroke-width="1.5"/>`;
    s += `<text x="${L + i * bw + bw / 2}" y="${y0 + 12}" text-anchor="middle" font-size="11" font-weight="700" paint-order="stroke" stroke="#fff" stroke-width="3">${m[i]}</text>`;
  });
  return s + `<line x1="${L}" x2="${W - 10}" y1="${y(0)}" y2="${y(0)}" stroke="#000" stroke-width="1.5"/></svg>`;
}
function kazanPie() {
  const v = [76.87, 108.79, 20.66, 38.81, 115.77, 25.82, 38.91], col = ['#7a1fff', '#3a86ff', '#ef3b3b', '#ff9a0d', '#ecc92d', '#ff2fc4', '#55ecff'];
  const tot = v.reduce((a, b) => a + b), cx = 180, cy = 125, r = 95, pt = (a, rr) => [cx + rr * Math.sin(a), cy - rr * Math.cos(a)];
  let a = 0, s = `<svg viewBox="0 0 360 250" width="360" role="img" aria-label="Круговая диаграмма с секторами 1–7">`, mids = [];
  v.forEach((x, i) => {
    const b = a + x / tot * 2 * Math.PI, [x1, y1] = pt(a, r), [x2, y2] = pt(b, r), mid = (a + b) / 2; mids.push(mid);
    s += `<path d="M${cx} ${cy}L${x1} ${y1}A${r} ${r} 0 ${b - a > Math.PI ? 1 : 0} 1 ${x2} ${y2}Z" fill="${col[i]}" stroke="#000" stroke-width="1.5"/>`;
    const [tx, ty] = pt(mid, r * .68); s += `<text x="${tx}" y="${ty + 5}" text-anchor="middle" font-size="15" font-weight="800">${i + 1}</text>`; a = b;
  });
  [[0, 'Советский'], [3, 'Московский'], [5, 'Вахитовский']].forEach(([i, n]) => {
    const [x1, y1] = pt(mids[i], r), [x2, y2] = pt(mids[i], r + 16), left = x2 < cx;
    s += `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="#000"/><text x="${x2 + (left ? -4 : 4)}" y="${y2 + (y2 > cy ? 12 : -2)}" text-anchor="${left ? 'end' : 'start'}" font-size="13" font-weight="800">${n}</text>`;
  });
  return s + '</svg>';
}
function clock(h, m) {
  const ha = (h % 12 + m / 60) * 30, ma = m * 6; let s = `<svg viewBox="0 0 200 200" width="170" role="img" aria-label="Наручные часы со стрелками">`;
  s += `<rect x="72" y="0" width="56" height="200" rx="8" fill="#2b2a2f"/><circle cx="100" cy="100" r="78" fill="#3a393f" stroke="#1b1a21" stroke-width="6"/><circle cx="100" cy="100" r="64" fill="#26252a"/>`;
  for (let i = 1; i <= 12; i++) { const a = i * Math.PI / 6; s += `<text x="${100 + 52 * Math.sin(a)}" y="${104 - 52 * Math.cos(a)}" text-anchor="middle" font-size="12" fill="#ddd" font-weight="700">${i}</text>`; }
  s += `<line x1="100" y1="100" x2="100" y2="66" stroke="#fff" stroke-width="5" stroke-linecap="round" transform="rotate(${ha} 100 100)"/>`;
  s += `<line x1="100" y1="100" x2="100" y2="48" stroke="#fff" stroke-width="3" stroke-linecap="round" transform="rotate(${ma} 100 100)"/><circle cx="100" cy="100" r="4" fill="#fff"/></svg>`;
  return s;
}
const trapezoid = () => {
  let s = `<svg viewBox="0 0 220 150" width="220" role="img" aria-label="Четырёхугольник на клетчатой бумаге">`;
  for (let i = 0; i <= 6; i++) s += `<line x1="${20 + i * 30}" y1="10" x2="${20 + i * 30}" y2="140" stroke="#c9c9c9"/>`;
  for (let j = 0; j <= 4; j++) s += `<line x1="10" y1="${15 + j * 30}" x2="210" y2="${15 + j * 30}" stroke="#c9c9c9"/>`;
  return s + `<polygon points="50,45 110,45 170,105 50,105" fill="rgba(226,53,43,.12)" stroke="#1b1a21" stroke-width="2.5"/></svg>`;
};
